    &lt;ActionInfo&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
      &lt;Description&gt;Calcul Zile CO in luna sesiunii curente&lt;/Description&gt;
      &lt;ActionType&gt;RunSql&lt;/ActionType&gt;
      &lt;OrderIndex&gt;1&lt;/OrderIndex&gt;
      &lt;LastModified&gt;2026-04-17T13:34:22.013&lt;/LastModified&gt;
      &lt;LastModifiedBy&gt;9&lt;/LastModifiedBy&gt;
      &lt;ActionData&gt;{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;SELECT\n    ISNULL(\n        SUM(\n            CASE WHEN MONTH(Interval1DatadeInceput) = @Luna AND YEAR(Interval1DatadeInceput) = @Anul\n                 THEN NrZileCO1 ELSE 0 END\n          + CASE WHEN MONTH(Interval2DatadeInceput) = @Luna AND YEAR(Interval2DatadeInceput) = @Anul\n                 THEN NrZileCO2 ELSE 0 END\n          + CASE WHEN MONTH(Interval3DatadeInceput) = @Luna AND YEAR(Interval3DatadeInceput) = @Anul\n                 THEN NrZileCO3 ELSE 0 END\n        ), 0\n    ) AS TotalZileCO_Luna\nFROM app.ConcediudeOdihna\nWHERE Marca = @marca;\n&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[GET:p_Marca]&quot;,&quot;name&quot;:&quot;marca&quot;}],&quot;OutputTokenName&quot;:&quot;row&quot;,&quot;ExtractColumns&quot;:[],&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false}&lt;/ActionData&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculZileCOLunar&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;MetadataJson&gt;{}&lt;/MetadataJson&gt;
      &lt;Metadata /&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
