      &lt;Description&gt;Zile Lucratoare&lt;/Description&gt;
      &lt;ActionType&gt;ExecuteActions&lt;/ActionType&gt;
      &lt;OrderIndex&gt;1&lt;/OrderIndex&gt;
      &lt;LastModified&gt;2026-04-17T13:34:21.907&lt;/LastModified&gt;
      &lt;LastModifiedBy&gt;9&lt;/LastModifiedBy&gt;
      &lt;ActionData&gt;{&quot;ActionList&quot;:[{&quot;Title&quot;:&quot;Run SQL Query&quot;,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Description&quot;:&quot;Preluare Zile Lucratoare&quot;,&quot;Condition&quot;:&quot;0&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;;WITH Zile AS (\n    SELECT DATEFROMPARTS(@Anul, @Luna, 1) AS Data\n    UNION ALL\n    SELECT DATEADD(DAY, 1, Data)\n    FROM Zile\n    WHERE MONTH(DATEADD(DAY, 1, Data)) = @Luna\n)\nSELECT COUNT(*) AS ZileLucratoare\nFROM Zile\nWHERE DATENAME(WEEKDAY, Data) NOT IN (&#39;Saturday&#39;, &#39;Sunday&#39;)\nOPTION (MAXRECURSION 40);\n&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:&quot;ZileLucratoare&quot;,&quot;ExtractColumns&quot;:&quot;&quot;,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false},&quot;$_uid&quot;:&quot;action17764327911699320&quot;,&quot;$_isOpen&quot;:false,&quot;$_isLoaded&quot;:true,&quot;$_isFocus&quot;:true,&quot;EventName&quot;:&quot;click&quot;,&quot;Definition&quot;:{&quot;Id&quot;:&quot;RunSql&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Run SQL Query&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Executes the specified SQL query, optionally storing the output for use in other actions.&quot;},&quot;TypeStr&quot;:&quot;DnnSharp.Common.Actions.Data.ExecuteSql, DnnSharp.Common.Actions&quot;,&quot;Final&quot;:false,&quot;IsClientAction&quot;:false,&quot;Groups&quot;:[],&quot;Parameters&quot;:[{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;DbConnector&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Database&quot;},&quot;HelpText&quot;:{},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;ActionCredentials&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;Selection&quot;:&quot;Single&quot;,&quot;Type&quot;:&quot;Database&quot;},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[{&quot;TypeStr&quot;:&quot;DnnSharp.Common2.Services.PlantAnApp.ConfigConditions.IsPlantAnApp,DnnSharp.Common2&quot;,&quot;Settings&quot;:{}}],&quot;$_cleanHashKey&quot;:&quot;17762517010499420&quot;},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;ConnectionString&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Override Connection String&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;By default, the SQL will run against the built-in database or the selected Connection. Use this field to override the connection string. Also supports the name of a connection string from the web.config. It will respect the Provider (ODBC, SqlClient, etc.). Can contain Tokens. Read more about &amp;lt;a href=\&quot;http://www.connectionstrings.com/\&quot; target=\&quot;_blank\&quot;&amp;gt;supported formats&amp;lt;/a&amp;gt;.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;QueryTimeout&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Query Timeout&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Set a time in seconds after which a query will time out. The default is set 10 minutes or 600 seconds also this parameter can&#39;t be negative or under 10 seconds. Can contain Tokens. &quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;SqlQuery&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;SQL Query&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;SQL to execute. Can contain Tokens. &amp;lt;br/&amp;gt; &amp;lt;div style=\&quot;color:red\&quot;&amp;gt;WARNING!&amp;lt;/div&amp;gt; We encourage using binding parameters instead of using the tokens directly on sql query. Just use @param instead of [token] and bind below values as shown: Parameter Name: param ; Parameter Value: [token]. This will keep your database safe.&amp;lt;br/&amp;gt;&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Code&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;CodeMirrorMode&quot;:&quot;sql&quot;,&quot;AiAssist&quot;:&quot;sql&quot;},&quot;Validation&quot;:[{&quot;Type&quot;:&quot;Required&quot;,&quot;From&quot;:null,&quot;For&quot;:null,&quot;Settings&quot;:{}}],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;BindTokens&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Bind Tokens&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Bind the parameters above with a value or token. e.g. P. Name:param, P. Value:[token] &quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;NameValueCollection&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;NameColumn&quot;:&quot;Parameter Name&quot;,&quot;ValueColumn&quot;:&quot;Parameter Value&quot;,&quot;ButtonName&quot;:&quot;Bind more data&quot;},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;OutputTokenName&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Store Result&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Optionally, provide a token name that will store the result. For example, store IDs generated by inserts or select data that is needed by other actions. If the query returns more than one column, you can access them using [&amp;amp;lt;OutputTokenName&amp;amp;gt;:&amp;amp;lt;ColumnName&amp;amp;gt;] syntax. Date fields generate additional tokens - [&amp;amp;lt;OutputTokenName&amp;amp;gt;:&amp;amp;lt;ColumnName&amp;amp;gt;:ISO], [&amp;amp;lt;OutputTokenName&amp;amp;gt;:&amp;amp;lt;ColumnName&amp;amp;gt;:ISODate], [&amp;amp;lt;OutputTokenName&amp;amp;gt;:&amp;amp;lt;ColumnName&amp;amp;gt;:ISOAsUtc].&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;ExtractColumns&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Extract Columns&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Optionally, provide an association table to map columns into tokens. For date columns additional tokens are generated - [&amp;amp;lt;Column&amp;amp;gt;:ISO], [&amp;amp;lt;Column&amp;amp;gt;:ISODate], [&amp;amp;lt;Column&amp;amp;gt;:ISOAsUtc]. Supports Tokens.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;NameValueCollection&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;NameColumn&quot;:&quot;Column Name&quot;,&quot;ValueColumn&quot;:&quot;Store As&quot;,&quot;ButtonName&quot;:&quot;Extract More Data&quot;},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;OnError&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;On Error&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Define a list of actions to run on error. Otherwise, an error message is returned which will contain the underlying error if debug mode is on. Tokens available in this context: [Exception], [ExceptionType], [ExceptionMessage], [ExceptionStack]&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{&quot;default&quot;:&quot;[]&quot;},&quot;Default&quot;:null,&quot;Type&quot;:&quot;ActionList&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;Event&quot;:&quot;OnError&quot;},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;ShowErrors&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Show Errors&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Show errors raised from SQL. This is useful for example if the error is a nicely formatted error message.&amp;lt;br/&amp;gt;Note that if this option is turned on, admins will always get a full error message and regular users will get a generic error message.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{&quot;default&quot;:&quot;False&quot;},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Boolean&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]}],&quot;Output&quot;:[{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;OutputTokenName&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Store Result&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Optionally, provide a token name that will store the result. For example, store IDs generated by inserts or select data that is needed by other actions. If the query returns more than one column, you can access them using [&amp;amp;lt;OutputTokenName&amp;amp;gt;:&amp;amp;lt;ColumnName&amp;amp;gt;] syntax. Date fields generate additional tokens - [&amp;amp;lt;OutputTokenName&amp;amp;gt;:&amp;amp;lt;ColumnName&amp;amp;gt;:ISO], [&amp;amp;lt;OutputTokenName&amp;amp;gt;:&amp;amp;lt;ColumnName&amp;amp;gt;:ISODate], [&amp;amp;lt;OutputTokenName&amp;amp;gt;:&amp;amp;lt;ColumnName&amp;amp;gt;:ISOAsUtc].&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;ExtractColumns&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Extract Columns&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Optionally, provide an association table to map columns into tokens. For date columns additional tokens are generated - [&amp;amp;lt;Column&amp;amp;gt;:ISO], [&amp;amp;lt;Column&amp;amp;gt;:ISODate], [&amp;amp;lt;Column&amp;amp;gt;:ISOAsUtc]. Supports Tokens.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;NameValueCollection&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;NameColumn&quot;:&quot;Column Name&quot;,&quot;ValueColumn&quot;:&quot;Store As&quot;,&quot;ButtonName&quot;:&quot;Extract More Data&quot;,&quot;OutputToken&quot;:&quot;ValueColumn&quot;},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]}],&quot;Settings&quot;:{&quot;Group&quot;:&quot;Data&quot;,&quot;FeatureFlag&quot;:&quot;Standard.DataIntegration&quot;},&quot;Conditions&quot;:null,&quot;isLicensed&quot;:true,&quot;feature&quot;:&quot;standard.dataintegration&quot;,&quot;featureUpgradeMessage&quot;:&quot;Unlock advanced database capabilities: run SQL queries, load users into context, create lists, and automate with DataBase triggers. Access powerful data sources and token types for seamless integration.&quot;}},{&quot;Title&quot;:&quot;Create/Update Tokens&quot;,&quot;ActionType&quot;:&quot;ApplyTokens&quot;,&quot;Description&quot;:&quot;Zile Lucratoare&quot;,&quot;Condition&quot;:&quot;0&quot;,&quot;Parameters&quot;:{&quot;Tokens&quot;:[{&quot;value&quot;:&quot;[ZileLucratoare]&quot;,&quot;name&quot;:&quot;ZileLucratoareLunar&quot;}],&quot;TokenizeTokenNames&quot;:&quot;&quot;,&quot;RecursionCount&quot;:&quot;1&quot;},&quot;$_uid&quot;:&quot;action17764327911696616&quot;,&quot;$_isOpen&quot;:false,&quot;$_isLoaded&quot;:true,&quot;$_isFocus&quot;:true,&quot;EventName&quot;:&quot;click&quot;,&quot;Definition&quot;:{&quot;Id&quot;:&quot;ApplyTokens&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Create/Update Tokens&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Creates or updates tokens in the current execution tokens. Optionally, it can tokenize values recursively.&quot;},&quot;TypeStr&quot;:&quot;DnnSharp.Common.Actions.Code.ApplyTokens, DnnSharp.Common.Actions&quot;,&quot;Final&quot;:false,&quot;IsClientAction&quot;:false,&quot;Groups&quot;:[],&quot;Parameters&quot;:[{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;Tokens&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Tokens&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Expressions to tokenize. Supports Tokens.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;NameValueCollection&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;NameColumn&quot;:&quot;Token Name&quot;,&quot;ValueColumn&quot;:&quot;Token Value&quot;,&quot;ValueColumnType&quot;:&quot;LargeText&quot;,&quot;ButtonName&quot;:&quot;Add&quot;,&quot;SupportsOrdering&quot;:true},&quot;Validation&quot;:[{&quot;Type&quot;:&quot;required&quot;,&quot;From&quot;:null,&quot;For&quot;:&quot;NameColumn&quot;,&quot;Settings&quot;:{}}],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;TokenizeTokenNames&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Tokenize Token Names&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Token Value always supports Tokens. Check this option to also support Tokens in the Token Name. Usage example: If [Index] has the value of 1, using a Token Name of \&quot;Customer[Index]\&quot; will assign the Token Value to \&quot;Customer1\&quot;.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Boolean&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;RecursionCount&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Number of Recursions&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Specify how many times to apply tokenization. This is useful when tokens contain other tokens that also need to be replaced. Note that this presents a security risk when the expression has content from untrusted users. Supports Tokens.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{&quot;default&quot;:&quot;1&quot;},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[{&quot;Type&quot;:&quot;required&quot;,&quot;From&quot;:null,&quot;For&quot;:null,&quot;Settings&quot;:{}}],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]}],&quot;Output&quot;:[{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;Tokens&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Tokens&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Expressions to tokenize. Supports Tokens.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;NameValueCollection&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;NameColumn&quot;:&quot;Token Name&quot;,&qu