    &lt;ActionInfo&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
      &lt;Description&gt;Creare Token pentru Zile CO pentru marca selectată + luna/an din Session.&lt;/Description&gt;
      &lt;ActionType&gt;ApplyTokens&lt;/ActionType&gt;
      &lt;OrderIndex&gt;2&lt;/OrderIndex&gt;
      &lt;LastModified&gt;2026-04-17T13:34:22.03&lt;/LastModified&gt;
      &lt;LastModifiedBy&gt;9&lt;/LastModifiedBy&gt;
      &lt;ActionData&gt;{&quot;Tokens&quot;:[{&quot;value&quot;:&quot;[row:TotalZileCO_Luna]&quot;,&quot;name&quot;:&quot;ZileCOLuna&quot;}],&quot;TokenizeTokenNames&quot;:&quot;&quot;,&quot;RecursionCount&quot;:&quot;1&quot;}&lt;/ActionData&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculZileCOLunar&lt;/FieldName&gt;
