    &lt;ActionInfo&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
      &lt;Description&gt;Exceptii Calcul Lichidare&lt;/Description&gt;
      &lt;ActionType&gt;ExecuteActions&lt;/ActionType&gt;
      &lt;OrderIndex&gt;2&lt;/OrderIndex&gt;
      &lt;LastModified&gt;2026-04-17T13:34:21.907&lt;/LastModified&gt;
      &lt;LastModifiedBy&gt;9&lt;/LastModifiedBy&gt;
      &lt;ActionData&gt;{&quot;ActionList&quot;:[{&quot;Title&quot;:&quot;Run SQL Query&quot;,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Description&quot;:&quot;Calcul Numar Exceptii&quot;,&quot;Condition&quot;:&quot;&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;;WITH Parametri AS (\n    SELECT\n        [Initializari:ZileLucratoare_old(Anul = [GetOrSession:YearV],Luna = [GetOrSession:MonthV])] AS ZileLucratoare\n)\n\nSELECT COUNT(*) AS NrExceptii\nFROM (\n    SELECT a.Id\n    FROM app.Salariat a\nCROSS JOIN Parametri p\n    OUTER APPLY (\n    SELECT\n        SUM(\n            CASE\n                WHEN c.Interval1DatadeInceput IS NOT NULL\n                 AND MONTH(c.Interval1DatadeInceput) = @Luna\n                 AND YEAR (c.Interval1DatadeInceput) = @Anul\n                THEN ISNULL(c.NrZileCO1, 0)\n                ELSE 0\n            END\n          + CASE\n                WHEN c.Interval2DatadeInceput IS NOT NULL\n                 AND MONTH(c.Interval2DatadeInceput) = @Luna\n                 AND YEAR (c.Interval2DatadeInceput) = @Anul\n                THEN ISNULL(c.NrZileCO2, 0)\n                ELSE 0\n            END\n          + CASE\n                WHEN c.Interval3DatadeInceput IS NOT NULL\n                 AND MONTH(c.Interval3DatadeInceput) = @Luna\n                 AND YEAR (c.Interval3DatadeInceput) = @Anul\n                THEN ISNULL(c.NrZileCO3, 0)\n                ELSE 0\n            END\n        ) AS ZileCOLuna\n    FROM app.ConcediudeOdihna c\n    WHERE c.Marca        = a.Marca\n      AND c.CodSucursala = @CodSucursala\n) co\n\n    OUTER APPLY (\n        SELECT\n            SUM(m.TotZileLucratoare) AS ZileCMLuna\n        FROM app.ConcediuMedical m\n        WHERE m.Marca = a.Marca\n          AND m.CodSucursala = @CodSucursala\n          AND m.AnulDePlata = @Anul\n          AND m.LunaDePlata = @Luna\n    ) cm\n\n    WHERE\n        a.Anul = @Anul\n        AND a.Luna = @Luna\n        AND a.CodSucursala = @CodSucursala\n        AND (\n            p.ZileLucratoare\n            - ISNULL(co.ZileCOLuna,0)\n            - ISNULL(cm.ZileCMLuna,0)\n        ) &amp;lt;= 0\n) x;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:&quot;p_NrExceptii&quot;,&quot;ExtractColumns&quot;:&quot;&quot;,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false},&quot;$_uid&quot;:&quot;action17762523724803404&quot;,&quot;$_isOpen&quot;:false,&quot;$_isLoaded&quot;:true,&quot;$_isFocus&quot;:true,&quot;EventName&quot;:&quot;click&quot;,&quot;Definition&quot;:{&quot;Id&quot;:&quot;RunSql&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Run SQL Query&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Executes the specified SQL query, optionally storing the output for use in other actions.&quot;},&quot;TypeStr&quot;:&quot;DnnSharp.Common.Actions.Data.ExecuteSql, DnnSharp.Common.Actions&quot;,&quot;Final&quot;:false,&quot;IsClientAction&quot;:false,&quot;Groups&quot;:[],&quot;Parameters&quot;:[{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;DbConnector&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Database&quot;},&quot;HelpText&quot;:{},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;ActionCredentials&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;Selection&quot;:&quot;Single&quot;,&quot;Type&quot;:&quot;Database&quot;},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[{&quot;TypeStr&quot;:&quot;DnnSharp.