se.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Code&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;HideTime&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Hide (with transition^) after (ms)&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Time in which the toast will close automatically. Time is in milliseconds. Supports Tokens&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{&quot;default&quot;:&quot;1000&quot;},&quot;Default&quot;:null,&quot;Type&quot;:&quot;text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;Stack&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Stack Length&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;1 if there should be only one toast at a time or a number representing the maximum number of toasts to be shown at a time. Supports Tokens.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{&quot;default&quot;:&quot;1&quot;},&quot;Default&quot;:null,&quot;Type&quot;:&quot;text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;ToastPosition&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Toast Position&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Positions on screen.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{&quot;default&quot;:&quot;bottom-center&quot;},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Select&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;Items&quot;:{&quot;bottom-left&quot;:{&quot;default&quot;:&quot;Bottom Left&quot;},&quot;bottom-right&quot;:{&quot;default&quot;:&quot;Bottom Right&quot;},&quot;bottom-center&quot;:{&quot;default&quot;:&quot;Bottom Center&quot;},&quot;top-right&quot;:{&quot;default&quot;:&quot;Top Right&quot;},&quot;top-left&quot;:{&quot;default&quot;:&quot;Top Left&quot;},&quot;top-center&quot;:{&quot;default&quot;:&quot;Top Center&quot;},&quot;mid-center&quot;:{&quot;default&quot;:&quot;Middle Center&quot;}}},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;TextAlignment&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Text Alignment&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Text Alignment.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{&quot;default&quot;:&quot;left&quot;},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Select&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;Items&quot;:{&quot;left&quot;:{&quot;default&quot;:&quot;Left&quot;},&quot;right&quot;:{&quot;default&quot;:&quot;Right&quot;},&quot;center&quot;:{&quot;default&quot;:&quot;Center&quot;}}},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;ShowLoader&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Show Loader&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Displays a progress bar.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Boolean&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;LoaderColor&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Loader Color&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;The color of the progress bar (eg. red #00ff00 rgb(0,0,255)). Supports Tokens.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;ShowCondition&quot;:&quot;itemParameters[&#39;ShowLoader&#39;]&quot;},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]}],&quot;Output&quot;:[],&quot;Settings&quot;:{&quot;Group&quot;:&quot;Message&quot;},&quot;Conditions&quot;:[{&quot;TypeStr&quot;:&quot;PlantAnApp.Dnn.Config.Conditions.IsForModule, PlantAnApp.Dnn&quot;,&quot;Settings&quot;:{&quot;AppCodes&quot;:[&quot;AFORM&quot;,&quot;AGRID&quot;]}}],&quot;isLicensed&quot;:true}}],&quot;OnError&quot;:[]}&lt;/ActionData&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculLichidare&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;MetadataJson&gt;{}&lt;/MetadataJson&gt;
      &lt;Metadata /&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
      &lt;Description&gt;Calcul Lichidare&lt;/Description&gt;
      &lt;ActionType&gt;RunSql&lt;/ActionType&gt;
      &lt;OrderIndex&gt;4&lt;/OrderIndex&gt;
      &lt;Condition&gt;0&lt;/Condition&gt;
      &lt;LastModified&gt;2026-04-17T13:34:21.937&lt;/LastModified&gt;
      &lt;LastModifiedBy&gt;9&lt;/LastModifiedBy&gt;
      &lt;ActionData&gt;{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;/*=====================================================\n    0️⃣ Declarare Statusuri\n=====================================================*/\nDECLARE @StatusDraft INT\nDECLARE @StatusBlocat INT\n\nSELECT @StatusDraft = Id \nFROM app.StatusCalcul \nWHERE Denumire = &#39;Draft&#39;\n\nSELECT @StatusBlocat = Id \nFROM app.StatusCalcul \nWHERE Denumire = &#39;Blocat&#39;\n\n\n/*=====================================================\n    1️⃣ Creează ControlLichidare dacă nu există\n=====================================================*/\nIF NOT EXISTS (\n    SELECT 1\n    FROM app.ControlLichidare\n    WHERE Anul = @Anul\n      AND Luna = @Luna\n      AND CodSucursala = @CodSucursala\n)\nBEGIN\n    INSERT INTO app.ControlLichidare\n    (\n        Anul,\n        Luna,\n        CodSucursala,\n        Status,\n        CreatDe,\n        DataCreare\n    )\n    VALUES\n    (\n        @Anul,\n        @Luna,\n        @CodSucursala,\n        @StatusDraft,\n        @UserName,\n        GETDATE()\n    )\nEND\n\n\n/*=====================================================\n    2️⃣ Oprește dacă luna este Blocată\n=====================================================*/\nIF EXISTS (\n    SELECT 1\n    FROM app.ControlLichidare\n    WHERE Anul = @Anul\n      AND Luna = @Luna\n      AND CodSucursala = @CodSucursala\n      AND Status = @StatusBlocat\n)\nBEGIN\n    RAISERROR (&#39;Luna este blocata. Deblocati pentru recalcul.&#39;,16,1)\n    RETURN\nEND\n\n\n/*=====================================================\n    3️⃣ Ștergere calcul existent\n=====================================================*/\nDELETE FROM app.CalculLichidare\nWHERE Anul = @Anul\n  AND Luna = @Luna\n  AND CodSucursala = @CodSucursala\n\n\n/*=====================================================\n    4️⃣ Motor calcul\n=====================================================*/\n\n;WITH Parametri AS \n(\n    ( SELECT [Initializari:ZileLucratoare_old(Anul = [GetOrSession:YearV],Luna = [GetOrSession:MonthV])] AS ZileLucratoare )\n)\n\nINSERT INTO app.CalculLichidare\n(\n    IdSalariat,\n    CodSucursala,\n    Marca,\n    TipNorma,\n    ZileLucratoare,\n    ZileCO,\n    ZileCM,\n    ZileLucrate,\n    OreLucrate,\n    SalariuBrut,\n    SalBrutEfectiv,\n    TicheteMasa,\n    Agenti,\n    Remiza,\n    AlteDrepturi,\n    BrutContributiv,\n    TotalBrut,\n    CAS,\n    CASS,\n    CAM,\n    BazaImpozabila,\n    ImpozitVenit,\n    CAR,\n    PensiiAlimentare,\n    PensiiFacultative,\n    AlteRetineri,\n    VenitNet,\n    SalariuNet,\n    NetDePlata,\n    Anul,\n    Luna,\n    DataCalcul,\n    Status\n)\n\nSELECT\n    a.Id,\n    @CodSucursala,\n    a.Marca,\n    a.TipNorma,\n\n    p.ZileLucratoare,\n    ISNULL(co.ZileCOLuna,0),\n    ISNULL(cm.ZileCMLuna,0),\n    zl.ZileLucrate,\n\n    ca.OreLucrate,\n    b.Salariu,\n    ca.SalBrutEfectiv,\n    ca.TicheteTotale,\n    ISNULL(ag.SumaAgent,0),\n    ISNULL(rem.Sume_Remiza,0),\n    0,\n    ca.BrutContributiv,\n    ca.TotalBrut,\n    ca.CAS,\n    ca.CASS,\n    0,\n    ca.BazaImpozabila,\n    ca.ImpozitVenit,\n    0, --CAR\n    ISNULL(pa.PensiiAlimentare,0),\n    0, --Pensie Facultativa\n    0,\n    ca.VenitNet,\n    ca.SalariuNet,\n    CASE \n   WHEN ca.SalariuNet - ISNULL(pa.PensiiAlimentare,0) &amp;lt; 0\n   THEN 0\n   ELSE ca.SalariuNet - ISNULL(pa.PensiiAlimentare,0)\nEND ,\n  \n    @Anul,\n    @Luna,\n    GETDATE(),\n    @StatusDraft\n\nFROM app.Salariat a\nLEFT JOIN app.NomGrilaSalarizare b\n       ON b.Clasa = a.Clasa\n      AND b.TipMediu = &#39;U&#39;\n\nLEFT JOIN app.TSTichetMasa t\n       ON t.Anul = @Anul\n      AND t.Luna = @Luna\n\nCROSS JOIN Parametri p\n\nOUTER APPLY (\n    SELECT\n        SUM(\n              CASE WHEN MONTH(c.Interval1DatadeInceput)=@Luna\n               AND YEAR(c.Interval1DatadeInceput)=@Anul\n              THEN ISNULL(c.NrZileCO1,0) ELSE 0 END\n            + CASE WHEN MONTH(c.Interval2DatadeInceput)=@Luna\n               AND YEAR(c.Interval2DatadeInceput)=@Anul\n              THEN ISNULL(c.NrZileCO2,0) ELSE 0 END\n            + CASE WHEN MONTH(c.Interval3DatadeInceput)=@Luna\n               AND YEAR(c.Interval3DatadeInceput)=@Anul\n              THEN ISNULL(c.NrZileCO3,0) ELSE 0 END\n        ) AS ZileCOLuna\n    FROM app.ConcediudeOdihna c\n    WHERE c.Marca = a.Marca\n      AND c.CodSucursala = @CodSucursala\n) co\n\nOUTER APPLY (\n    SELECT SUM(m.TotZileLucratoare) AS ZileCMLuna\n    FROM app.ConcediuMedical m\n    WHERE m.Marca = a.Marca\n      AND m.CodSucursala = @CodSucursala\n      AND m.AnulDePlata = @Anul\n      AND m.LunaDePlata = @Luna\n) cm\n\nCROSS APPLY (\n    SELECT\n        CASE\n            WHEN p.ZileLucratoare\n                 - ISNULL(co.ZileCOLuna,0)\n                 - ISNULL(cm.ZileCMLuna,0) &amp;lt; 0\n            THEN 0\n            ELSE p.ZileLucratoare\n                 - ISNULL(co.ZileCOLuna,0)\n                 - ISNULL(cm.ZileCMLuna,0)\n        END AS ZileLucrate\n) zl\n\nOUTER APPLY (\n    SELECT SUM(ISNULL(ca2.Suma,0)) AS SumaAgent\n    FROM app.CalculAgent ca2\n    WHERE ca2.Marca = a.Marca\n      AND ca2.Anul = @Anul\n      AND ca2.Luna = @Luna\n      AND ca2.CodSucursala = @CodSucursala\n) ag\n\nOUTER APPLY (\n    SELECT SUM(ISNULL(x.Suma,0)) AS Sume_Remiza\n    FROM app.Remiza x\n    WHERE x.Marca = a.Marca\n      AND x.Anul = @Anul\n      AND x.Luna = @Luna\n      AND x.CodSucursala = @CodSucursala\n) rem\nOUTER APPLY (\n    SELECT \n        SUM(\n              ISNULL(p.Rata,0)\n            + ISNULL(p.Rest,0)\n            + ISNULL(p.Taxa,0)\n            + ISNULL(p.Taxam,0)\n        ) AS PensiiAlimentare\n    FROM app.PensieAlimentara p\n    WHERE p.Marca = a.Marca\n      AND p.Anul = @Anul\n      AND p.Luna = @Luna\n      AND p.CodSucursala = @CodSucursala\n) pa\n\nCROSS APPLY (\n    SELECT\n        zl.ZileLucrate * a.TipNorma * 8 AS OreLucrate,\n        ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0) AS SalBrutEfectiv,\n        ISNULL(t.Valoare,0) * zl.ZileLucrate AS TicheteTotale,\n        (\n            ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n            + ISNULL(ag.SumaAgent,0)\n            + ISNULL(rem.Sume_Remiza,0)\n        ) AS BrutContributiv,\n        (\n            ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n            + ISNULL(ag.SumaAgent,0)\n            + ISNULL(rem.Sume_Remiza,0)\n            + (ISNULL(t.Valoare,0) * zl.ZileLucrate)\n        ) AS TotalBrut,\n        ROUND((\n            ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n            + ISNULL(ag.SumaAgent,0)\n            + ISNULL(rem.Sume_Remiza,0)\n        ) * 0.25,0) AS CAS,\n        ROUND((\n            ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n            + ISNULL(ag.SumaAgent,0)\n            + ISNULL(rem.Sume_Remiza,0)\n            + (ISNULL(t.Valoare,0) * zl.ZileLucrate)\n        ) * 0.10,0) AS CASS,\n        (\n            (\n                ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n                + ISNULL(ag.SumaAgent,0)\n                + ISNULL(rem.Sume_Remiza,0)\n            ) * 0.65\n        ) AS BazaImpozabila,\n        ROUND((\n            (\n                ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n                + ISNULL(ag.SumaAgent,0)\n                + ISNULL(rem.Sume_Remiza,0)\n            ) * 0.65\n        ) * 0.10,0) AS ImpozitVenit,\n        (\n            (\n                ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n                + ISNULL(ag.SumaAgent,0)\n                + ISNULL(rem.Sume_Remiza,0)\n            ) * 0.65\n        ) * 0.90 AS SalariuNet,\n        (\n            (\n                ROUND((b.Salariu / (p.ZileLucratoare * 8)) * (zl.ZileLucrate * a.TipNorma * 8),0)\n                + ISNULL(ag.SumaAgent,0)\n                + ISNULL(rem.Sume_Remiza,0)\n            ) * 0.65\n        ) * 0.90 AS VenitNet\n) ca\n\nWHERE \na.CodSucursala = @CodSucursala\nAND a.Anul = @Anul\nAND a.Luna = @Luna\n\n\n/*=====================================================\n    5️⃣ Validare: dacă nu s-a inserat nimic → eroare\n=====================================================*/\nIF NOT EXISTS (\n    SELECT 1\n    FROM app.CalculLichidare\n    WHERE Anul = @Anul\n      AND Luna = @Luna\n      AND CodSucursala = @CodSucursala\n)\nBEGIN\n    RAISERROR (&#39;Nu s-au generat inregistrari pentru aceasta luna.&#39;,16,1)\n    RETURN\nEND\n\n&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[User:UserName]&quot;,&quot;name&quot;:&quot;Username&quot;}],&quot;OutputTokenName&quot;:&quot;&quot;,&quot;ExtractColumns&quot;:&quot;&quot;,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false}&lt;/ActionData&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculLichidare&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;MetadataJson&gt;{}&lt;/MetadataJson&gt;
      &lt;Metadata /&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
      &lt;Description&gt;Redirectare catre Calcul Lichidare&lt;/Description&gt;
      &lt;ActionType&gt;RedirectToPage&lt;/ActionType&gt;
