      &lt;Condition /&gt;
      &lt;LastModified&gt;2026-04-17T13:34:21.937&lt;/LastModified&gt;
      &lt;LastModifiedBy&gt;9&lt;/LastModifiedBy&gt;
      &lt;ActionData&gt;{&quot;PageId&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:191,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;EnforceCurrentLocale&quot;:&quot;&quot;,&quot;QueryString&quot;:&quot;&quot;,&quot;QueryStringUseUrlProvider&quot;:true,&quot;OpenInPopup&quot;:&quot;&quot;,&quot;PopupTitle&quot;:&quot;&quot;,&quot;OpenInNewTab&quot;:&quot;&quot;}&lt;/ActionData&gt;
      &lt;ModuleId&gt;811&lt;/ModuleId&gt;
      &lt;FieldName&gt;CalculLichidare&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;MetadataJson&gt;{}&lt;/MetadataJson&gt;
      &lt;Metadata /&gt;
    &lt;/ActionInfo&gt;
